<?php
namespace PharmaSure\Integrations\Services;
final class IntegrationService{private $db;private $p;public function __construct(){global $wpdb;$this->db=$wpdb;$this->p=$wpdb->prefix.'ps_';}
	public function configure($tenant,$branch,array $data,$actor){$type=sanitize_key($data['integration_type']??'');$adapter=sanitize_key($data['adapter_key']??'');$name=sanitize_text_field($data['display_name']??'');$supported=array('email'=>array('wordpress_email'),'webhook'=>array('signed_webhook'),'sms'=>array(),'payment'=>array(),'accounting'=>array(),'insurer'=>array());if(!$type||!array_key_exists($type,$supported)||!in_array($adapter,$supported[$type],true)){return new \WP_Error('adapter_unavailable','No installed adapter matches this integration type and key.',array('status'=>501));}if(!$name){return new \WP_Error('invalid_integration','A display name is required.',array('status'=>422));}$encrypted=null;if(!empty($data['credentials'])){$encrypted=(new CredentialVault())->encrypt((array)$data['credentials']);if(is_wp_error($encrypted)){return $encrypted;}}$branch=(int)$branch;$sql=$this->db->prepare("INSERT INTO {$this->p}integration_configs (tenant_id,branch_id,integration_type,adapter_key,display_name,endpoint_url,encrypted_credentials,status,created_by,created_at,updated_at) VALUES (%d,%d,%s,%s,%s,%s,%s,'active',%d,%s,%s) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),endpoint_url=VALUES(endpoint_url),encrypted_credentials=COALESCE(VALUES(encrypted_credentials),encrypted_credentials),status='active',updated_at=VALUES(updated_at)",$tenant,$branch,$type,$adapter,$name,esc_url_raw($data['endpoint_url']??'')?:null,$encrypted,$actor,current_time('mysql',true),current_time('mysql',true));$this->db->query($sql);if($this->db->last_error){return new \WP_Error('integration_not_saved','Integration configuration could not be saved.',array('status'=>500));}$id=(int)($this->db->insert_id?:$this->db->get_var($this->db->prepare("SELECT id FROM {$this->p}integration_configs WHERE tenant_id=%d AND branch_id=%d AND integration_type=%s AND adapter_key=%s",$tenant,$branch,$type,$adapter)));do_action('pharmasure_audit_log',array('tenant_id'=>$tenant,'actor_id'=>$actor,'action'=>'integration.configured','object_type'=>'integration_config','object_id'=>$id,'details'=>array('type'=>$type,'adapter_key'=>$adapter,'branch_id'=>$branch)));return array('id'=>$id,'status'=>'active');}
	public function enqueue($tenant,$config_id,$event_type,array $payload,$key){$config=$this->db->get_row($this->db->prepare("SELECT id FROM {$this->p}integration_configs WHERE id=%d AND tenant_id=%d AND status='active'",$config_id,$tenant),ARRAY_A);$key=sanitize_text_field($key);if(!$config||!$key||!sanitize_key($event_type)){return new \WP_Error('invalid_delivery','Active integration, event type and idempotency key are required.',array('status'=>422));}$existing=$this->db->get_row($this->db->prepare("SELECT * FROM {$this->p}integration_deliveries WHERE tenant_id=%d AND idempotency_key=%s",$tenant,$key),ARRAY_A);if($existing){if((int)$existing['config_id']!==$config_id){return new \WP_Error('idempotency_conflict','Idempotency key belongs to another integration.',array('status'=>409));}$existing['idempotent_replay']=true;return $existing;}$this->db->insert($this->p.'integration_deliveries',array('tenant_id'=>$tenant,'config_id'=>$config_id,'idempotency_key'=>$key,'event_type'=>sanitize_key($event_type),'payload'=>wp_json_encode($payload),'status'=>'pending','next_attempt_at'=>current_time('mysql',true),'created_at'=>current_time('mysql',true)));return $this->db->insert_id?array('id'=>(int)$this->db->insert_id,'status'=>'pending'):new \WP_Error('delivery_not_queued','Delivery could not be queued.',array('status'=>500));}
}
